#!/usr/bin/env bash
# .github/scripts/formula.sh
#
# Writes the Homebrew formula for a release to stdout, pointing it at the
# binaries that release carries and their sha256s. The formula workflow runs
# this and commits the result, so the formula is generated rather than kept in
# step by hand.
#
#   .github/scripts/formula.sh v0.1.0 dist

set -euo pipefail

if [ "$#" -ne 2 ]; then
  echo "usage: ${0##*/} <tag> <binaries-directory>" >&2
  exit 2
fi

tag="$1"
dist="$2"
version="${tag#v}"

# The sha256 of one release binary, as named by its release target.
sha_for() {
  local binary="$dist/tnotify-$1"

  if [ ! -r "$binary" ]; then
    echo "${0##*/}: cannot read $binary" >&2
    exit 1
  fi

  sha256sum "$binary" | cut -d' ' -f1
}

url_for() {
  printf 'https://github.com/karnull/tnotify/releases/download/%s/tnotify-%s' "$tag" "$1"
}

macos_arm_sha="$(sha_for macOS-apple-silicon)"
macos_intel_sha="$(sha_for macOS-intel)"
linux_arm_sha="$(sha_for linux-arm64)"
linux_intel_sha="$(sha_for linux-x64)"

cat <<FORMULA
# Formula/tnotify.rb
#
# Generated by .github/scripts/formula.sh when a release is cut. Anything
# written here by hand is lost at the next release.

class Tnotify < Formula
  desc "Notifications and questions in a tmux popup, for panes nobody is watching"
  homepage "https://github.com/karnull/tnotify"
  version "$version"
  license "Apache-2.0"

  on_macos do
    on_arm do
      url "$(url_for macOS-apple-silicon)"
      sha256 "$macos_arm_sha"
    end

    on_intel do
      url "$(url_for macOS-intel)"
      sha256 "$macos_intel_sha"
    end
  end

  on_linux do
    on_arm do
      url "$(url_for linux-arm64)"
      sha256 "$linux_arm_sha"
    end

    on_intel do
      url "$(url_for linux-x64)"
      sha256 "$linux_intel_sha"
    end
  end

  # Each release target is a bare binary named for its platform.
  def install
    bin.install Dir["tnotify-*"].first => "tnotify"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/tnotify --version")
  end
end
FORMULA
